🐛 Describe the bug
I am trying to use libtorch + torch_tensorrt
Since I need a large array of size 1x6x320x320, I tried using malloc to first create the array locally, then use torch::from_blob().cuda() to send it to GPU.
I can print and see the values correctly from the torch cuda tensor.
However, when I later call free to release the malloc memory, I get the following error:

Here is the code
class array3DFloat
{
public:
    float* array;
    uint16_t n_rows=0, n_cols=0, n_channels=0;
    uint16_t row_index = 0, col_index = 0, gid = 0;
    uint32_t numElementsArray = 0;
    //
    array3DFloat(uint16_t n_rows, uint16_t n_cols, uint16_t n_channels, float init_val=99.99)
    {
        this->n_rows = n_rows;
        this->n_cols = n_cols;
        this->n_channels = n_channels;
        this->array = (float*)malloc(sizeof(float) * n_rows * n_cols * n_channels);
        this->numElementsArray = n_rows * n_cols * n_channels;
        //
        for(auto ch_index = 0; ch_index < this->n_channels; ch_index++)
        {
            for(auto r_index = 0; r_index < this->n_rows; r_index++)
            {
                for(auto c_index = 0; c_index < this->n_cols; c_index++)
                {
                    this->gid = this->n_rows * this->n_cols * ch_index + r_index * this->n_cols + c_index;

                    // sanity check
                    if(this->gid >= this->numElementsArray)
                    {
                        printf("ERROR: Array overflow likely...\n");
                    }

                    this->array[this->gid] = init_val;
                }
            }
        }
        //
        printf("Array init done\n");
    }

    inline void releaseArray()
    {
        free(this->array);
        printf("Array release..\n");
    }
};

auto bev = array3DFloat(2, 2, 2);
auto tensor_bev = torch::from_blob(bev.array, {2, 2, 2}).cuda();
cout << tensor_bev << endl;
bev.releaseArray();

Please help me understand this.
Best Regards
