🐛 Describe the bug
I am trying to run a simple Pytorch code using Libtorch 1.12.1. It runs perfectly under Release mode, but not with Debug. This problem happens when using the GPU.
I had to add /INCLUDE:"?ignore_this_library_placeholder@@YAHXZ" on VS linker to make GPU works on 1.12.1. As stated here.
When using an old Libtorch 1.8.2, the code runs fine on Release and Debug mode.
For 1.12.1 (Debug), It does load the model correctly but breaks in the  module.forward line.

That is the sample code I am using:
#include <torch/script.h> // One-stop header.

#include <iostream>
#include <string.h>
#include <memory>


using namespace std;

int main()
{

    string model_file = "UNet.pt";
    string img_file = "img.png";

    torch::Device device = torch::kCUDA;

    /*
     * ---- LOAD MODEL ----
    */

    torch::jit::script::Module module;
    try {
        // Deserialize the ScriptModule from a file using torch::jit::load().
        module = torch::jit::load(model_file, device);
    }
    catch (const c10::Error& e) {
        std::cerr << "error loading the model\n";
        std::cerr << e.msg() << std::endl;
        return -1;
    }
    std::cerr << "model loaded\n";


    /*
     * ---- Forward through model ----
    */

    at::Tensor tensor_image = torch::ones({ 1, 1, 224, 224});

    std::vector<torch::jit::IValue> tensor_image_jit;
    tensor_image_jit.push_back(tensor_image.to(device));

    // Execute the model and turn its output into a tensor.
    at::Tensor output = module.forward(tensor_image_jit).toTensor();
    output = output.to(torch::kCPU);
    output = output.toType(torch::kFloat32);

    std::cerr << "image processed\n";

    return 0;
}
